<?php require '../includes/config.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$st=$pdo->prepare("SELECT * FROM admins WHERE username=?");$st->execute([$_POST['username']]);$a=$st->fetch();if($a&&password_verify($_POST['password'],$a['password'])){$_SESSION['admin']=$a['id'];header('Location:dashboard.php');exit;}$error='Invalid admin credentials.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/css/admin.css"><title>Admin Login</title></head><body class="login-shell"><form class="login-card" method="post"><small>NOVACART PRO</small><h1>Admin control panel</h1><p>Manage products, orders, customers and messages.</p><?php if($error):?><div class="notice"><?=$error?></div><?php endif;?><div class="field"><label>Username</label><input name="username" value="admin" required></div><div class="field"><label>Password</label><input type="password" name="password" placeholder="Admin@123" required></div><button class="btn" style="width:100%">Sign in</button><p><a href="../index.php">← Back to store</a></p></form></body></html>
